/**
 * Checks of the record opened in Ekphrasis: whether it opens as a form, whether it is an authored
 * record rather than a file generated by a tool, whether the save of a form reaches it, and
 * whether the operating system lets that save write it.
 *
 * No check writes: the save route is followed up to the file that it would write, and the write
 * permission of that file is asked of the operating system, without any probe file.
 */
import { parseSchemaIdentifier, readSchemaField } from "../../domain";
import type { FormState } from "../form-service";
import type { SchemaFacts } from "./schema-checks";
import type { VaultInspector } from "./ports";
import { notPassed, passed, type CheckSubject, type DiagnosticCheck } from "./report";

/** Record displayed by the active view of Ekphrasis. */
export interface OpenedRecord {
  /** Vault path of the file. */
  readonly path: string;
  readonly text: string;
  /** Latest outcome of the form pipeline on `text`, or `null` while it runs. */
  readonly state: FormState | null;
}

const SUBJECTS = {
  form: {
    id: "record.form",
    consequence: "forms",
    dependency: "Form of the opened record",
    affects: "the form of this record",
  },
  authored: {
    id: "record.authored",
    consequence: "saving",
    dependency: "Origin of the opened file",
    affects: "edits of this file in the form",
  },
  indexed: {
    id: "record.indexed",
    consequence: "saving",
    dependency: "Vault file of the record",
    affects: "saving of this record",
  },
  write: {
    id: "record.write",
    consequence: "saving",
    dependency: "Write permission of the record",
    affects: "saving of this record",
  },
} as const satisfies Record<string, CheckSubject>;

const OPEN_A_RECORD =
  "Open an authored YAML record in Ekphrasis, then run the diagnostic again to check its form and its saving.";

export async function recordChecks(
  record: OpenedRecord | null,
  facts: SchemaFacts,
  vault: VaultInspector,
): Promise<readonly DiagnosticCheck[]> {
  if (record === null) {
    return [
      notPassed(
        "unavailable",
        SUBJECTS.form,
        "No YAML record is open in Ekphrasis.",
        OPEN_A_RECORD,
      ),
      notPassed(
        "unavailable",
        SUBJECTS.write,
        "No YAML record is open in Ekphrasis, so no save was followed.",
        OPEN_A_RECORD,
      ),
    ];
  }
  const checks = [formCheck(record, facts)];
  const generated = generatedKind(record, facts);
  if (generated !== null) {
    checks.push(
      notPassed("warning", SUBJECTS.authored, generated.observed, generated.action),
      notPassed(
        "unavailable",
        SUBJECTS.write,
        "Not checked: Ekphrasis never writes this file.",
        OPEN_A_RECORD,
      ),
    );
    return checks;
  }
  checks.push(passed(SUBJECTS.authored, `\`${record.path}\` is an authored record.`));
  if (!vault.isIndexedFile(record.path)) {
    checks.push(
      notPassed(
        "fail",
        SUBJECTS.indexed,
        `Obsidian does not index \`${record.path}\`, so the form cannot save it.`,
        "Move the record into a folder that Obsidian indexes, outside hidden folders and the configuration folder of the vault.",
      ),
    );
    return checks;
  }
  checks.push(
    passed(SUBJECTS.indexed, `Obsidian indexes \`${record.path}\`, which a save writes.`),
  );
  const access = await vault.writeAccess(record.path);
  switch (access.status) {
    case "writable":
      checks.push(
        passed(SUBJECTS.write, `The operating system lets Obsidian write \`${record.path}\`.`),
      );
      break;
    case "denied":
      checks.push(
        notPassed(
          "fail",
          SUBJECTS.write,
          `The operating system refuses to write \`${record.path}\` (${access.reason}).`,
          "Make the file writable for your user, for instance in the information panel of the file manager, and check that no synchronization service locks it.",
          [access.reason],
        ),
      );
      break;
    case "unknown":
      checks.push(
        notPassed(
          "unavailable",
          SUBJECTS.write,
          `The write permission of \`${record.path}\` cannot be checked here: ${access.reason}.`,
          "Edit a field and watch the file: a save that fails displays a notice. On a desktop computer, the diagnostic checks the permission itself.",
        ),
      );
  }
  return checks;
}

/** Whether and why the opened file is generated rather than authored. */
function generatedKind(
  record: OpenedRecord,
  facts: SchemaFacts,
): { readonly observed: string; readonly action: string } | null {
  const path = record.path;
  if (facts.generatedPaths.has(path)) {
    return {
      observed: `\`${path}\` is a schema or a registry generated by the provisioning tool of the project; Ekphrasis reads it but never writes it.`,
      action:
        "Change the source from which the tool generates this file, then generate it again; to fill a record, open an authored record.",
    };
  }
  const state = record.state;
  if (state?.status === "form" && state.model.root.lock === "read-only") {
    return {
      observed: `The schema \`${state.binding.reference}\` marks \`${path}\` read-only, as a generated view: the form refuses every edit.`,
      action:
        "Edit the authored records from which the view is generated, then generate the view again.",
    };
  }
  return null;
}

/** Outcome of the form pipeline on the opened record, as the view last displayed it. */
function formCheck(record: OpenedRecord, facts: SchemaFacts): DiagnosticCheck {
  const state = record.state;
  const path = record.path;
  if (state === null) {
    return notPassed(
      "unavailable",
      SUBJECTS.form,
      `The form of \`${path}\` is still being built.`,
      "Wait until the form displays, then run the diagnostic again.",
    );
  }
  switch (state.status) {
    case "form":
      return passed(
        SUBJECTS.form,
        `\`${path}\` opens as a form of \`${state.binding.reference}\` (\`${state.binding.schemaPath}\`).`,
      );
    case "unbound":
      const identifier = readSchemaField(record.text);
      const declared = identifier === null ? null : parseSchemaIdentifier(identifier);
      if (declared !== null) {
        const registered = facts.identifiers.some((candidate) => {
          const parsed = parseSchemaIdentifier(candidate);
          return parsed?.owner === declared.owner && parsed.type === declared.type;
        });
        if (!registered) {
          return passed(
            SUBJECTS.form,
            `The format \`${declared.owner}:${declared.type}\` is not registered, so \`${path}\` remains in the source view without a binding error.`,
          );
        }
      }
      return notPassed(
        "warning",
        SUBJECTS.form,
        `No \`_schema\` field, modeline or path rule binds \`${path}\`, so it opens in the source view.`,
        "Write the identifier of its contract in the field `_schema`, or add a path rule matching its path under *Path rules* in the settings of Ekphrasis.",
      );
    case "invalid-binding":
      return notPassed(
        "fail",
        SUBJECTS.form,
        `The binding \`${state.reference}\` of \`${path}\` does not resolve: ${state.reason}.`,
        state.source === "schema-field"
          ? "Check the identifier written in `_schema` against the registry, and the checks of the schema registry above."
          : "Correct the schema path written in the modeline or the path rule so that it names a schema file of the vault.",
        [state.reason],
      );
    case "parse-error":
      return notPassed(
        "fail",
        SUBJECTS.form,
        `The YAML text of \`${path}\` does not parse: ${state.error.message}`,
        "Open the source view and correct the YAML syntax at the line reported.",
        [state.error.message],
      );
    case "schema-error":
      return notPassed(
        "fail",
        SUBJECTS.form,
        `The schema \`${state.binding.schemaPath}\` of \`${path}\` does not load: ${state.error.message}`,
        `Repair or generate again the schema \`${state.error.schemaPath}\`; the checks of the schema registry above locate the defect.`,
        [state.error.message],
      );
  }
}
